// Generated by ai-hq earnings_notes/publish.py. One shared team login: the sign-in page sets a cookie
// stamped with the sign-in time and signed with the credentials, good for one day; HTTP Basic Auth still works for scripts. Credentials live in the
// Vercel project as DESK_USER / DESK_PASSWORD.
export const config = { matcher: ["/((?!favicon.ico).*)"] };
const COOKIE = "peak_desk";
const MAX_AGE = 60 * 60 * 24;                                                     // one day (Thomas, 2026-10-19)

export default async function middleware(req) {
  const user = process.env.DESK_USER || "";
  const pass = process.env.DESK_PASSWORD || "";
  if (!user || !pass) {
    return new Response("Earnings Desk: DESK_USER and DESK_PASSWORD are not set in Vercel.", { status: 503 });
  }
  const url = new URL(req.url);
  const path = url.pathname;
  if (path === "/login.html" || path.startsWith("/assets/")) return;          // the sign-in page and its picture
  if (path === "/logout") return redirect("/login.html", `${COOKIE}=; Path=/; Max-Age=0; HttpOnly; Secure; SameSite=Lax`);
  if (path === "/login" && req.method === "POST") {
    let form;
    try { form = await req.formData(); } catch (e) { return redirect("/login.html?err=1"); }
    const u = String(form.get("user") || ""), p = String(form.get("pass") || "");
    const next = safeNext(form.get("next"));
    if (u.length === user.length && p.length === pass.length && safeEqual(u, user) && safeEqual(p, pass)) {
      const at = String(Math.floor(Date.now() / 1000));
      return redirect(next, `${COOKIE}=${at}.${await token(user, pass, at)}; Path=/; Max-Age=${MAX_AGE}; HttpOnly; Secure; SameSite=Lax`);
    }
    return redirect("/login.html?err=1&next=" + encodeURIComponent(next));
  }
  if (path === "/login") return redirect("/login.html");
  const [at, sig] = cookie(req, COOKIE).split(".");                            // signed in within the day
  const age = Date.now() / 1000 - Number(at);
  if (sig && age >= 0 && age < MAX_AGE) {
    const want = await token(user, pass, at);
    if (sig.length === want.length && safeEqual(sig, want)) return;
  }
  const got = req.headers.get("authorization") || "";
  const basic = "Basic " + btoa(user + ":" + pass);
  if (got.length === basic.length && safeEqual(got, basic)) return;            // scripts and curl
  return redirect("/login.html?next=" + encodeURIComponent(path + url.search));
}

function redirect(to, setCookie) {
  const headers = { Location: to, "Cache-Control": "no-store" };
  if (setCookie) headers["Set-Cookie"] = setCookie;
  return new Response(null, { status: 303, headers });
}

function safeNext(v) {
  const s = String(v || "/");
  return s.startsWith("/") && !s.startsWith("//") ? s : "/";
}

function cookie(req, name) {
  const all = req.headers.get("cookie") || "";
  const m = all.match(new RegExp("(?:^|;\s*)" + name + "=([^;]+)"));
  return m ? m[1] : "";
}

async function token(user, pass, at) {
  const data = new TextEncoder().encode(`${user}:${pass}:peak-desk-v2:${at}`);
  const buf = await crypto.subtle.digest("SHA-256", data);
  return Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

function safeEqual(a, b) {
  let r = 0;
  for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return r === 0;
}
